// Naive Recursion – O(2^n)
FUNCTION fib(n):
    IF n <= 1: RETURN n
    RETURN fib(n-1) + fib(n-2)

// Memoization (Top-Down DP) – O(n)
memo = {}
FUNCTION fib_memo(n):
    IF n in memo: RETURN memo[n]
    IF n <= 1: RETURN n
    memo[n] = fib_memo(n-1) + fib_memo(n-2)
    RETURN memo[n]

// Tabulation (Bottom-Up DP) – O(n) time, O(1) space
FUNCTION fib_dp(n):
    IF n <= 1: RETURN n
    prev2 = 0, prev1 = 1
    FOR i FROM 2 TO n:
        curr = prev1 + prev2
        prev2 = prev1
        prev1 = curr
    RETURN prev1

