// Bank Transfer – ACID Example
FUNCTION transfer(fromAcc, toAcc, amount):
    BEGIN TRANSACTION
    TRY:
        // Atomicity: both must succeed or both fail
        fromAcc.balance -= amount    // Step 1
        IF fromAcc.balance < 0:
            RAISE Error('Insufficient funds')
        toAcc.balance += amount      // Step 2

        // Consistency: total money in system unchanged
        // Isolation: no other transaction sees partial state
        COMMIT TRANSACTION
        // Durability: changes written to disk permanently
    CATCH error:
        ROLLBACK TRANSACTION       // Atomicity guaranteed

