// Deadlock Example
RESOURCE A, B

PROCESS P1:
    ACQUIRE(A)        // P1 holds A
    WAIT(B)           // P1 waits for B — but P2 has B

PROCESS P2:
    ACQUIRE(B)        // P2 holds B
    WAIT(A)           // P2 waits for A — but P1 has A
// → DEADLOCK: P1 and P2 wait forever

// Prevention: Resource Ordering
// Always acquire resources in same fixed order
PROCESS P1:
    ACQUIRE(A) then ACQUIRE(B)
PROCESS P2:
    ACQUIRE(A) then ACQUIRE(B)  // same order — no circular wait

