// URL Shortening
FUNCTION shortenURL(longURL):
    id = autoIncrement()                  // get next unique ID
    shortKey = base62Encode(id)           // e.g. 1000000 → 'b8kJd'
    DB.store(shortKey, longURL)           // save mapping
    cache.set(shortKey, longURL, TTL=1hr)
    RETURN 'https://short.ly/' + shortKey

// base62 encoding uses a-z, A-Z, 0-9 = 62 chars
// 62^6 = ~56 billion unique short URLs

